import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  // Simplest cases
  it.todo("returns an empty grid for an empty grid — [] -> []");
  it.todo("kills a single lone cell (0 neighbors) — [(0,0)] -> []");

  // Rule 1 - Underpopulation (live cell with < 2 live neighbors dies)
  it.todo(
    "kills both cells of a horizontal pair, each having 1 neighbor — [(0,1),(1,1)] -> []",
  );

  // Rule 2 - Survival (live cell with 2 or 3 live neighbors lives on)
  it.todo(
    "keeps a live cell with exactly 2 live neighbors alive — (1,1) survives in [(0,1),(1,1),(2,1)]",
  );
  it.todo(
    "keeps a live cell with exactly 3 live neighbors alive — (1,1) survives in [(0,2),(1,2),(2,2),(1,1)]",
  );

  // Rule 3 - Overpopulation (live cell with > 3 live neighbors dies)
  it.todo(
    "kills a live cell with 4 live neighbors — (1,1) dies in [(0,2),(1,2),(2,2),(1,1),(1,0)]",
  );

  // Rule 4 - Reproduction (dead cell with exactly 3 live neighbors becomes alive)
  it.todo(
    "brings a dead cell with exactly 3 live neighbors to life — (1,1) becomes alive in [(0,2),(1,2),(0,1)]",
  );
  it.todo(
    "leaves a dead cell with 2 live neighbors dead — (1,1) stays dead in [(0,1),(2,1)]",
  );

  // Negative coordinates / infinite grid
  it.todo(
    "handles negative coordinates — block at [(-1,-1),(0,-1),(-1,0),(0,0)] is unchanged",
  );

  // Patterns
  it.todo(
    "keeps the block still life unchanged — [(0,0),(1,0),(0,1),(1,1)] -> same 4 cells",
  );
  it.todo(
    "oscillates the blinker from vertical to horizontal — [(0,0),(0,1),(0,2)] -> [(-1,1),(0,1),(1,1)]",
  );
  it.todo(
    "oscillates the blinker back to vertical after a second generation — [(-1,1),(0,1),(1,1)] -> [(0,0),(0,1),(0,2)]",
  );
});

