input.content:
export type Cell = [number, number];

const key = ([x, y]: Cell): string => `${x},${y}`;

const neighbours = ([x, y]: Cell): Cell[] => [
  [x - 1, y - 1],
  [x, y - 1],
  [x + 1, y - 1],
  [x - 1, y],
  [x + 1, y],
  [x - 1, y + 1],
  [x, y + 1],
  [x + 1, y + 1],
];

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const live = new Set(liveCells.map(key));

  const liveNeighbourCount = (cell: Cell): number =>
    neighbours(cell).filter((n) => live.has(key(n))).length;

  const candidates = new Map<string, Cell>();
  for (const cell of liveCells) {
    candidates.set(key(cell), cell);
    for (const neighbour of neighbours(cell)) {
      candidates.set(key(neighbour), neighbour);
    }
  }

  const survivors: Cell[] = [];
  for (const cell of candidates.values()) {
    const count = liveNeighbourCount(cell);
    const isAlive = live.has(key(cell));
    if (count === 3 || (isAlive && count === 2)) {
      survivors.push(cell);
    }
  }

  return survivors;
}

