// The order of cells in a generation carries no meaning, so compare as sorted sets.
const sorted = (cells: Cell[]): Cell[] =>
  [...cells].sort(([ax, ay], [bx, by]) => ax - bx || ay - by);

describe("Game of Life - Next Generation", () => {
  // Simplest cases
