  it("keeps a live cell with exactly 3 live neighbors alive — (1,1) survives in [(0,2),(1,2),(2,2),(1,1)]", () => {
    const result = nextGeneration([
      [0, 2],
      [1, 2],
      [2, 2],
      [1, 1],
    ]);

    expect(sorted(result)).toEqual(
      sorted([
        [0, 2],
        [1, 2],
        [2, 2],
